$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L '(?m)^var ZDEFAULT=1\.3,ZT=ZDEFAULT,ZC=ZDEFAULT,zoomSaveT=0;'
$r1=@'
// v28.xx (cw-camfar105), HIS ORDER (2026-10-20 evening): "default camera needs to be further away from player", then with his picture: "this is a good distance for default camera". His picture shows a pillager 6.4 percent of the screen height; 1.3 drew it 7.9 percent, so the default is 1.05 (1.3 x 6.4 / 7.9). Reverses the 1.3 of v31.85; a zoom he set himself stays.
var ZDEFAULT=1.05,ZT=ZDEFAULT,ZC=ZDEFAULT,zoomSaveT=0;
'@.Replace("`r",'')
$r1=$r1.TrimEnd("`n")
$a2=L "\['Numpad0','zoom to 130%'\]"
$r2="['Numpad0','zoom to 105%']"
$chk=@'
  {v:'VER',what:'a fresh profile boots at the 1.05 default camera (his picture), in career and in the demo, for both windows, and a saved zoom stays his',
   run:function(){
     if(typeof loadZoom!=='function'||typeof ZDEFAULT==='undefined') return 'the boot camera has no default loader';
     var bad=[], had=Object.prototype.hasOwnProperty.call(P,'zoom'), saved=P.zoom,
         oldZT=ZT, oldZC=ZC, oldSaveT=zoomSaveT, oldG=G,
         oldW=W, oldH=H, oldVX=VX, oldVY=VY, mx=mouse.x, my=mouse.y;
     function near(a,b,label){ if(!isFinite(a)||Math.abs(a-b)>0.001) bad.push(label+': '+a+' expected '+b); }
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       near(ZDEFAULT,1.05,'the default dial');
       // both modes and both windows load the same shared default: a fresh profile has no zoom field
       ['career','demo'].forEach(function(mode){
         [1,2].forEach(function(win){
           delete P.zoom; ZT=ZC=7; loadZoom();
           near(ZT,1.05,mode+' window '+win+' target'); near(ZC,1.05,mode+' window '+win+' eased camera');
         });
       });
       if(Object.prototype.hasOwnProperty.call(P,'zoom')) bad.push('loading the default wrote over the profile');
       [0.85,1.3,2.15].forEach(function(z){
         P.zoom=z; loadZoom();
         near(ZT,z,'saved target'); near(ZC,z,'saved eased camera');
       });
       G={sim:true,player:{x:2600,y:2000}};
       [[1920,1080],[3840,2160]].forEach(function(size){
         W=size[0]; H=size[1];
         delete P.zoom; loadZoom();
         var z=ZOOM(), res=hudRes();
         near(z,1.05*res,'default world scale '+W);
         near(W/z,1920/1.05,'world width '+W); near(H/z,1080/1.05,'world height '+W);
         VX=G.camX=G.player.x-W/(2*z); VY=G.camY=G.player.y-H*0.54/z;
         var s=w2s(G.player.x,0,G.player.y);
         near(s.x,W/2,'pillager x '+W); near(s.y,H*0.54,'pillager y '+W);
         mouse.x=W*0.62; mouse.y=H*0.38;
         var mw=mouseWorld(), back=w2s(mw.x,0,mw.y);
         near(back.x,mouse.x,'pointer x '+W); near(back.y,mouse.y,'pointer y '+W);
       });
       return bad.length?bad.join('; '):null;
     } catch(err){
       return 'camera default check: '+String(err&&err.message||err);
     } finally {
       G=oldG; W=oldW; H=oldH; VX=oldVX; VY=oldVY;
       if(had) P.zoom=saved; else delete P.zoom;
       ZT=oldZT; ZC=oldZC; zoomSaveT=oldSaveT;
       mouse.x=mx; mouse.y=my;
       __topClear();
     }
   }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='CAMERA FURTHER OUT'
  why='His 10-20 order and picture: the default camera sits further from the pillager. The default dial goes from 1.3 to 1.05, matching the pillager size in his picture; a saved personal zoom stays as chosen.'
  now='The default camera is further out. Reset zoom returns to 105 percent.'
  edits=@([ordered]@{anchor=$a1;replacement=$r1},[ordered]@{anchor=$a2;replacement=$r2})
  check=$chk
}
'written'
$od=$(if($env:MK_OUT_DIR){$env:MK_OUT_DIR}else{'C:\claudecode\dark raiders\tools\handoff\drafts'})
[IO.File]::WriteAllText((Join-Path $od 'draft-cw-camfar105.json'),($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
